# Get list of Slack channels to see what exists
curl -s "$SLACK_URL/api/conversations.list" -H "Authorization: Bearer ***REDACTED***" -H "Content-Type: application/json" -d '{"types":"public_channel,private_channel","limit":200,"exclude_archived":true}' 2>&1 | python3 -c "
import sys, json
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data.get('channels', []):
        print(f\"{ch['id']} | {ch['name']} | {ch.get('num_members', 0)} members\")
else:
    print('Error:', data)
" 2>&1

# Try GET method with query params instead
curl -s "$SLACK_URL/api/conversations.list?types=public_channel,private_channel&limit=200&exclude_archived=true" -H "Authorization: Bearer ***REDACTED***" 2>&1 | python3 -c "
import sys, json
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data.get('channels', []):
        print(f\"{ch['id']} | {ch['name']} | {ch.get('num_members', 0)} members\")
else:
    print('Error:', json.dumps(data, indent=2))
" 2>&1

# Get all users in the Slack workspace
curl -s "$SLACK_URL/api/users.list" -H "Authorization: Bearer ***REDACTED***" 2>&1 | python3 -c "
import sys, json
data = json.load(sys.stdin)
if data.get('ok'):
    for u in data.get('members', []):
        print(f\"{u['id']} | {u['name']} | {u.get('profile', {}).get('email', '')} | deleted={u.get('deleted', False)} | is_bot={u.get('is_bot', False)}\")
else:
    print('Error:', json.dumps(data, indent=2))
" 2>&1
